package server_test

import (
	"net/http"
	"net/http/cookiejar"
	"net/http/httptest"
	"strings"
	"testing"
)

func TestJarKeepsSecureCookie(t *testing.T) {
	h := http.NewServeMux()
	h.HandleFunc("POST /set", func(w http.ResponseWriter, r *http.Request) {
		http.SetCookie(w, &http.Cookie{Name: "session", Value: "v", Path: "/", HttpOnly: true, Secure: true, SameSite: http.SameSiteLaxMode, MaxAge: 3600})
		w.WriteHeader(204)
	})
	h.HandleFunc("GET /ask", func(w http.ResponseWriter, r *http.Request) {
		t.Logf("got cookies: %v", r.Cookies())
		w.WriteHeader(204)
	})
	srv := httptest.NewServer(h)
	defer srv.Close()
	jar, _ := cookiejar.New(nil)
	c := &http.Client{Jar: jar}
