// probePost is the diagnostic hook of the internal probe: it sends a signup
// body to the handler given, over the same code path post() uses.
func probePost(tb testing.TB, h http.Handler, body string) (*http.Response, map[string]any) {
	tb.Helper()
	srv := httptest.NewServer(h)
	tb.Cleanup(srv.Close)
	req, err := http.NewRequest(http.MethodPost, srv.URL+"/api/signup", strings.NewReader(body))
