package server_test

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/http/cookiejar"
	"net/http/httptest"
	"strings"
	"testing"
	"time"

	"golang.org/x/crypto/bcrypt"

	"git.aisoftwarefactory.world/linkshort2/linkshort2/internal/server"
	"git.aisoftwarefactory.world/linkshort2/linkshort2/internal/store"
)

// authPassword is the password of the auth tests: 10 characters, as long as
// signup requires.
const authPassword = "hunter2hunter2"

// post sends a request to an endpoint and returns its response with the body
// read and, when it is JSON, decoded. The caller's client keeps cookies, so
// the session cookie a login sets reaches that test's next request.
func post(t *testing.T, client *http.Client, method, url, body string) (*http.Response, map[string]any) {
	t.Helper()
	req, err := http.NewRequest(method, url, strings.NewReader(body))
	if err != nil {
		t.Fatalf("%s %s: %v", method, url, err)
	}
	req.Header.Set("Content-Type", "application/json")
	return do(t, client, req)
}

// getJSON asks an endpoint with GET.
func getJSON(t *testing.T, client *http.Client, url string) (*http.Response, map[string]any) {
	t.Helper()
	req, err := http.NewRequest(http.MethodGet, url, nil)
	if err != nil {
		t.Fatalf("GET %s: %v", url, err)
	}
	return do(t, client, req)
}

func do(t *testing.T, client *http.Client, req *http.Request) (*http.Response, map[string]any) {
	t.Helper()
	res, err := client.Do(req)
	if err != nil {
		t.Fatalf("%s %s: %v", req.Method, req.URL, err)
	}
	t.Cleanup(func() { _ = res.Body.Close() })
	raw, err := io.ReadAll(res.Body)
	if err != nil {
		t.Fatalf("%s %s: read body: %v", req.Method, req.URL, err)
	}
	body := map[string]any{}
	if len(raw) > 0 {
		if err := json.Unmarshal(raw, &body); err != nil {
			body = map[string]any{"raw": string(raw)}
		}
	}
	return res, body
}

// sessionCookieOf names the session cookie a response set, and reports
// whether it set one at all.
func sessionCookieOf(res *http.Response) (*http.Cookie, bool) {
	var found *http.Cookie
	for _, c := range res.Cookies() {
		if c.Name == server.SessionCookie {
			found = c
		}
	}
	return found, found != nil
}

// newCookieJar keeps the cookies of one test client over its requests.
func newCookieJar(t *testing.T) http.CookieJar {
	t.Helper()
	jar, err := cookiejar.New(nil)
	if err != nil {
		t.Fatal(err)
	}
	return jar
}

// authedClient is a client that carries the session cookie of a login to
// every request, whatever scheme the server answers on: an http test server
// cannot keep a Secure cookie in a jar, because no browser would send one
// over an insecure connection either.
func authedClient(cookie string) *http.Client {
	c := &http.Client{}
	c.Transport = roundTripFunc(func(req *http.Request) (*http.Response, error) {
		req.AddCookie(&http.Cookie{Name: server.SessionCookie, Value: cookie})
		return http.DefaultTransport.RoundTrip(req)
	})
	return c
}

type roundTripFunc func(*http.Request) (*http.Response, error)

func (f roundTripFunc) RoundTrip(req *http.Request) (*http.Response, error) { return f(req) }

// TestSignup is the card's acceptance item: a valid signup returns 201, and
// what is not a valid account answers 400 or 409. Over a store of the test's
// own it also shows what signup hands it: the bcrypt hash, never the
// password in the clear.
func TestSignup(t *testing.T) {
	f := openStore(t)
	srv := httptest.NewServer(server.New(server.Config{Store: f}))
	defer srv.Close()
	client := srv.Client()

	res, body := post(t, client, http.MethodPost, srv.URL+"/api/signup",
		`{"email":"sebastian@example.com","password":"`+authPassword+`"}`)
	if res.StatusCode != http.StatusCreated {

	srv := httptest.NewServer(server.New(server.Config{Store: st}))
	t.Cleanup(srv.Close)
	jarred := &http.Client{Jar: newCookieJar(t)}

	res, body := post(t, jarred, http.MethodPost, srv.URL+"/api/signup",
		`{"email":"ada@example.com","password":"`+authPassword+`"}`)
	if res.StatusCode != http.StatusCreated {
		t.Fatalf("POST /api/signup: status %d body %v, want 201", res.StatusCode, body)
	}
	res, body = post(t, jarred, http.MethodPost, srv.URL+"/api/login",
		`{"email":"ada@example.com","password":"`+authPassword+`"}`)
	if res.StatusCode != http.StatusNoContent {
		t.Fatalf("POST /api/login: status %d body %v, want 204", res.StatusCode, body)
	}
	set, ok := sessionCookieOf(res)
	if !ok || set.Value == "" {
		t.Fatalf("login set no session cookie: %v", res.Cookies())
	}
	return srv, authedClient(set.Value), set.Value, st
}
